return items.map(item => {

  const rsi = item.json.data?.rsi;

  function classifyRsi(rsi) {
    if (rsi == null) return null;
    if (rsi < 20) return "extreme_oversold";
    if (rsi < 30) return "oversold";
    if (rsi < 45) return "weak_bearish_momentum";
    if (rsi <= 55) return "balanced";
    if (rsi <= 70) return "bullish_momentum";
    if (rsi <= 80) return "overbought";
    return "extreme_overbought";
  }

  item.json.data.rsi_state = classifyRsi(rsi);

  return item;
});

return items.map(item => {

  const close = item.json.data?.close_price;
  const ma7 = item.json.data?.ma_7;

  function calculateStretch(close, ma7) {
    if (close == null) return null;
    if (ma7 == null || ma7 === 0) return null;

    return ((close - ma7) / ma7) * 100;
  }

  function classifyStretch(stretch) {
    if (stretch == null) return null;

    if (stretch < -5) return "deep_pullback";
    if (stretch > 5) return "extended";
    return "near_mean";
  }

  const stretch = calculateStretch(close, ma7);

  return {
    json: {
      ...item.json,
      data: {
        ...item.json.data,
        price_vs_ma7_percent: stretch,
        stretch_state: classifyStretch(stretch)
      }
    }
  };

});

return items.map(item => {

  const {
    rsi_state,
    trend_direction,
    bullish_cross,
    bearish_cross,
    volume_spike
  } = item.json.data || {};

  function determineTrigger() {

    // 1️⃣ RSI pullback logic
    if (rsi_state === "oversold" && trend_direction === "bullish") {
      return "RSI_pullback_long";
    }

    if (rsi_state === "overbought" && trend_direction === "bearish") {
      return "RSI_pullback_short";
    }

    // 2️⃣ MA cross logic
    if (bullish_cross === true) {
      return "Bullish_MA_Cross";
    }

    if (bearish_cross === true) {
      return "Bearish_MA_Cross";
    }

    // 3️⃣ Volume breakout logic
    if (volume_spike === true && trend_direction === "bullish") {
      return "Bullish_Volume_Breakout";
    }

    if (volume_spike === true && trend_direction === "bearish") {
      return "Bearish_Volume_Breakout";
    }

    return "None";
  }

  return {
    json: {
      ...item.json,
      data: {
        ...item.json.data,
        primary_trigger: determineTrigger()
      }
    }
  };

});

