return items.map(item => {

 const close = item.json.data?.close_price;
const ma3 = item.json.data?.ma_3;
const ma7 = item.json.data?.ma_7;

  function classifyTrend(close, ma3, ma7) {
    if (close === undefined || ma3 === undefined || ma7 === undefined) {
      return null;
    }

    if (close > ma7 && ma3 > ma7) return "bullish";
    if (close < ma7 && ma3 < ma7) return "bearish";
    return "sideways";
  }

  return {
    json: {
      ...item.json,
      trend_direction: classifyTrend(close, ma3, ma7)
    }
  };

});

return items.map(item => {

  const volatility = item.json.data?.volatility;

  function classifyVolatility(vol) {
    if (vol == null) return null;

    // vol = 7-day std of pct_change

    if (vol < 3) return "low";
    if (vol < 6) return "medium";
    return "high";
  }

  return {
    json: {
      ...item.json,
      data: {
        ...item.json.data,
        volatility_regime: classifyVolatility(volatility)
      }
    }
  };

});

return items.map(item => {

  const d = item.json.data;
  const trend = item.json.trend_direction;

  let score = 0;

  // 1️⃣ Trend bias
  if (trend === "bullish") score += 1;
  if (trend === "bearish") score -= 1;

  // 2️⃣ RSI momentum
  if (d.rsi_state === "bullish_momentum") score += 1;
  if (d.rsi_state === "weak_bearish_momentum") score -= 1;
  if (d.rsi_state === "overbought") score -= 1;
  if (d.rsi_state === "oversold") score += 1;

  // 3️⃣ MA strength
  if (d.trend_strength_score != null) {
    if (d.trend_strength_score > 5) score += 1;
    if (d.trend_strength_score < -5) score -= 1;
  }

  // 4️⃣ Volatility expansion bias
  if (d.volatility_regime === "high") {
    if (trend === "bullish") score += 1;
    if (trend === "bearish") score -= 1;
  }

  // Clamp score between -3 and +3
  if (score > 3) score = 3;
  if (score < -3) score = -3;

  // Classification label
  let pressure_label = "neutral_pressure";
  if (score >= 2) pressure_label = "strong_bullish_pressure";
  if (score === 1) pressure_label = "mild_bullish_pressure";
  if (score <= -2) pressure_label = "strong_bearish_pressure";
  if (score === -1) pressure_label = "mild_bearish_pressure";

  return {
    json: {
      ...item.json,
      data: {
        ...d,
        market_pressure_score: score,
        market_pressure_state: pressure_label
      }
    }
  };

});

return items.map(item => {

  const d = item.json.data || {};

  /* -------------------------
     RSI CATEGORY (5 levels)
  --------------------------*/
  let rsi_category = "Unknown";
  if (typeof d.rsi === "number") {
    if (d.rsi <= 20) rsi_category = "Extreme_Oversold";
    else if (d.rsi <= 35) rsi_category = "Oversold";
    else if (d.rsi < 65) rsi_category = "Neutral";
    else if (d.rsi < 80) rsi_category = "Overbought";
    else rsi_category = "Extreme_Overbought";
  }


  /* -------------------------
     VOLATILITY CATEGORY
  --------------------------*/
  let volatility_category = "Unknown";
  if (typeof d.volatility === "number") {
    if (d.volatility <= 1) volatility_category = "Very_Low";
    else if (d.volatility <= 3) volatility_category = "Low";
    else if (d.volatility <= 6) volatility_category = "Medium";
    else if (d.volatility <= 10) volatility_category = "High";
    else volatility_category = "Very_High";
  }


  /* -------------------------
     TREND STRENGTH CATEGORY
  --------------------------*/
  let trend_strength_category = "Unknown";
  if (typeof d.trend_strength_score === "number") {
    if (d.trend_strength_score <= 2) trend_strength_category = "Very_Weak";
    else if (d.trend_strength_score <= 4) trend_strength_category = "Weak";
    else if (d.trend_strength_score <= 6) trend_strength_category = "Moderate";
    else if (d.trend_strength_score <= 8) trend_strength_category = "Strong";
    else trend_strength_category = "Very_Strong";
  }


  /* -------------------------
     PRICE VS MA7 CATEGORY
  --------------------------*/
  let price_vs_ma7_category = "Unknown";
  if (typeof d.price_vs_ma7_percent === "number") {
    if (d.price_vs_ma7_percent <= -5) price_vs_ma7_category = "Far_Below_MA";
    else if (d.price_vs_ma7_percent <= -1) price_vs_ma7_category = "Below_MA";
    else if (d.price_vs_ma7_percent < 1) price_vs_ma7_category = "Near_MA";
    else if (d.price_vs_ma7_percent < 5) price_vs_ma7_category = "Above_MA";
    else price_vs_ma7_category = "Far_Above_MA";
  }


  /* -------------------------
     DAILY PERCENT CHANGE CATEGORY
  --------------------------*/
  let pct_change_category = "Unknown";
  if (typeof d.pct_change === "number") {
    if (d.pct_change <= -5) pct_change_category = "Strong_Down";
    else if (d.pct_change <= -1) pct_change_category = "Mild_Down";
    else if (d.pct_change < 1) pct_change_category = "Flat";
    else if (d.pct_change < 5) pct_change_category = "Mild_Up";
    else pct_change_category = "Strong_Up";
  }


  /* -------------------------
     DOMINANCE CATEGORY
  --------------------------*/
  let dominance_category = "Unknown";
  if (typeof d.dominance_ratio === "number") {
    if (d.dominance_ratio <= 0.01) dominance_category = "Very_Low";
    else if (d.dominance_ratio <= 0.03) dominance_category = "Low";
    else if (d.dominance_ratio <= 0.08) dominance_category = "Medium";
    else if (d.dominance_ratio <= 0.15) dominance_category = "High";
    else dominance_category = "Very_High";
  }


  /* -------------------------
     VOLUME SPIKE CATEGORY
  --------------------------*/
  let volume_spike_category = "None";
  if (typeof d.volume_spike === "number") {
    if (d.volume_spike <= 10) volume_spike_category = "Low";
    else if (d.volume_spike <= 25) volume_spike_category = "Moderate";
    else if (d.volume_spike <= 50) volume_spike_category = "Strong";
    else volume_spike_category = "Extreme";
  }


  /* -------------------------
     EMBEDDING CONTEXT
  --------------------------*/

  const embedding_context = {
    trend_direction: item.json.trend_direction || "Unknown",
    rsi_category,
    volatility_category,
    trend_strength_category,
    price_vs_ma7_category,
    pct_change_category,
    dominance_category,
    volume_spike_category,
    rsi_state: d.rsi_state || "Unknown",
    volatility_regime: d.volatility_regime || "Unknown",
    stretch_state: d.stretch_state || "Unknown",
    market_pressure_state: d.market_pressure_state || "Unknown",
    bullish_cross: d.bullish_cross ?? false,
    bearish_cross: d.bearish_cross ?? false
  };


  return {
    json: {
      ...item.json,
      categorized: {
        rsi_category,
        volatility_category,
        trend_strength_category,
        price_vs_ma7_category,
        pct_change_category,
        dominance_category,
        volume_spike_category
      },
      embedding_context
    }
  };

});

